insert into home_sections(type,position,enabled,data) values ('hero',10,true,'{"title": {"de": "Afrikanische & asiatische Lebensmittel, Kosmetik und Deko.", "en": "African & Asian groceries, beauty and home goods."}, "text": {"de": "Über 750 Produkte aus über 30 Ländern – von Gari und Egusi bis Sheabutter und Jebena. Versand in ganz Deutschland oder kostenlos in Kaiserslautern abholen.", "en": "Over 750 products from over 30 countries – from gari and egusi to shea butter and jebena. Delivered across Germany, or pick up for free in Kaiserslautern."}, "cta1Label": {"de": "Zum Shop", "en": "Shop now"}, "cta1Href": "/shop", "cta2Label": {"de": "Rezeptideen", "en": "Recipe ideas"}, "cta2Href": "/rezepte", "images": [], "autoFill": true, "facts": [{"text": {"de": "Kostenloser Versand ab 69 €", "en": "Free delivery from €69"}}, {"text": {"de": "Kostenlose Abholung", "en": "Free pickup"}}, {"text": {"de": "Tiefkühl-Express", "en": "Frozen express"}}]}'::jsonb);
