insert into home_sections(type,position,enabled,data) values ('usp',100,true,'{"title": {"de": "Einkaufen bei Greenland", "en": "Shopping with Greenland"}, "items": [{"icon": "truck", "title": {"de": "Versand in ganz Deutschland", "en": "Delivery across Germany"}, "text": {"de": "DHL in 2–3 Werktagen, ab 69 € kostenlos.", "en": "DHL in 2–3 working days, free from €69."}}, {"icon": "bag", "title": {"de": "Kostenlos abholen", "en": "Free pickup"}, "text": {"de": "Online bestellen, im Laden in Kaiserslautern abholen.", "en": "Order online, collect in Kaiserslautern."}}, {"icon": "snow", "title": {"de": "Tiefkühl-Express", "en": "Frozen express"}, "text": {"de": "Fisch und Fleisch in der Kühlbox, am nächsten Tag da.", "en": "Fish and meat in an insulated box, next day."}}, {"icon": "chat", "title": {"de": "Fragen? WhatsApp", "en": "Questions? WhatsApp"}, "text": {"de": "Wir helfen dir gern weiter.", "en": "We are happy to help."}}]}'::jsonb);
insert into home_sections(type,position,enabled,data) values ('story',110,true,'{"image": "https://cdn.selldone.com/app/shops/15718/categories/grl000428ethiopiantraditionalporcelaincoffeesetwithgolddisplayjpeg952ea94bda4f19jpgc33db612f043b14de1a454ef37d5f88c512.jpg", "title": {"de": "Ein Laden für die Diaspora", "en": "A shop for the diaspora"}, "text": {"de": "Greenland Afro Asia Store in Kaiserslautern führt die Zutaten und Pflegeprodukte, die du von zu Hause kennst, und das, was man in Deutschland nur schwer findet.\n\nFehlt dir etwas? Schreib uns – wir bestellen es gerne für dich.", "en": "Greenland Afro Asia Store in Kaiserslautern stocks the ingredients and care products you know from home, and the ones that are hard to find in Germany.\n\nMissing something? Message us and we''ll order it in for you."}, "ctaLabel": {"de": "Mehr über uns", "en": "More about us"}, "ctaHref": "/info/ueber-uns", "imageSide": "right", "color": "none"}'::jsonb);
insert into home_sections(type,position,enabled,data) values ('faq',120,true,'{"title": {"de": "Häufige Fragen", "en": "Questions people ask"}, "items": [{"q": {"de": "Wie lange dauert die Lieferung?", "en": "How long does delivery take?"}, "a": {"de": "Innerhalb Deutschlands 2–3 Werktage mit DHL. In Kaiserslautern und Umgebung liefern wir am selben oder nächsten Tag.", "en": "Within Germany 2–3 working days by DHL. In and around Kaiserslautern we deliver the same or next day."}}, {"q": {"de": "Kann ich Tiefkühlware bestellen?", "en": "Can I order frozen products?"}, "a": {"de": "Ja. Tiefkühlware versenden wir montags bis mittwochs per Express in einer isolierten Box. Mindestbestellwert 50 €.", "en": "Yes. Frozen products ship Monday to Wednesday by express in an insulated box. Minimum order €50."}}, {"q": {"de": "Kann ich im Laden abholen?", "en": "Can I pick up in store?"}, "a": {"de": "Ja, immer kostenlos. Wir schicken dir eine WhatsApp-Nachricht, sobald deine Bestellung bereit ist.", "en": "Yes, always free. We send you a WhatsApp message when your order is ready."}}, {"q": {"de": "Ein Produkt fehlt. Könnt ihr es besorgen?", "en": "A product is missing. Can you get it?"}, "a": {"de": "Sehr gerne. Schreib uns auf WhatsApp, was du suchst.", "en": "Happily. Message us on WhatsApp with what you are looking for."}}]}'::jsonb);
insert into home_sections(type,position,enabled,data) values ('newsletter',130,true,'{"title": {"de": "Neue Ware und Angebote zuerst erfahren", "en": "Hear about new stock and offers first"}, "text": {"de": "Einmal im Monat, kein Spam.", "en": "Once a month, no spam."}, "buttonLabel": {"de": "Anmelden", "en": "Sign up"}, "note": {"de": "Du kannst dich jederzeit abmelden.", "en": "You can unsubscribe at any time."}, "color": "sand"}'::jsonb);
